/*
 * A159294  Number of ways that a 1 X n rectangular tile T, marked into n unit
 *          squares, can be surrounded by one layer of copies of itself laid
 *          in the plane grid generated by the units of T. Ways that differ by
 *          rotation or reflection are not counted as different. The
 *          surrounded tile is the exact surrounded r...
 * https://oeis.org/A159294
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn, easy
 * Formula:   a(n) = (1/16)*( n^4 + 30 n^3 + 246 n^2 + 476 n + 256 + (n odd ?
 *            6 n + 9 : 0) ), a(1)=1
 * Range:     u8 n <= 1, u16 n <= 9, u32 n <= 329, u64 n <= 1000,
 *            u128 n <= 1000, big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

#include <stdint.h>

seq_t a(idx_t n)
{
    /* Handle the offset */
    if (n == 0) return 0;        /* undefined, return 0 for safety */
    if (n == 1) return 1;

    /* Cast to seq_t for all arithmetic */
    seq_t nn = (seq_t)n;

    /* Compute polynomial */
    seq_t term = nn * nn * nn * nn;                /* n^4 */
    term += (seq_t)30 * nn * nn * nn;              /* 30 n^3 */
    term += (seq_t)246 * nn * nn;                 /* 246 n^2 */
    term += (seq_t)476 * nn;                      /* 476 n */
    term += 256;                                  /* constant */

    /* Add odd adjustment */
    if (n & 1) {
        term += (seq_t)6 * nn + 9;
    }

    /* Divide by 16 */
    return term / 16;
}
